(function(){
 'use strict';
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const safeURL=s=>/^https?:\/\//i.test(s||'')?s:'';
 const link=(url,label,cls='text-button')=>safeURL(url)?`<a href="${e(url)}" target="_blank" rel="noopener noreferrer" class="${cls}">${e(label)} ↗</a>`:'';
 const n=x=>x===null||x===undefined?'확인 필요':Number(x).toLocaleString('ko-KR');
 const people=x=>x===null?'인원 확인 필요':`${n(x)}명`;
 const money=x=>x===null?'업체 문의':`${n(x)}원`;
 let db=null,error=false,pending=false,limit=12,hallView='list';
 let filters=HallModel.initial(),openFilter='',draft=null,regionGroup='seoul';
 const compare=new Set();
 let hallSaved;
 try{const ids=JSON.parse(localStorage.getItem('viewdding.halls.saved.v1')||'[]');hallSaved=new Set(Array.isArray(ids)?ids.filter(x=>typeof x==='string'):[])}catch{hallSaved=new Set()}
 const persist=()=>{try{localStorage.setItem('viewdding.halls.saved.v1',JSON.stringify([...hallSaved]));return true}catch{return false}};
 const all=()=>db?.halls||[];
 const byId=id=>all().find(h=>h.id===id);
 const matches=()=>HallModel.filter(all(),filters,hallSaved);
 const selected=(a,b)=>a===b?' selected':'';
 const options=(values,current,blank)=>`<option value="">${blank}</option>`+values.map(v=>`<option value="${e(v)}"${selected(v,current)}>${e(v)}</option>`).join('');
 const types=['밝은 홀','어두운 홀','야외 웨딩','채플','하우스 웨딩','호텔 웨딩','전통 · 한옥'];
 function photo(h,detail=false){const p=h.photo;return p&&(!p.expires||p.expires>=new Date().toISOString().slice(0,10))?`<figure class="hall-photo ${detail?'hall-photo-large':''}"><img src="${e(p.url)}" alt="${e(h.name+' · '+h.hall+' — '+p.label)}" loading="lazy" referrerpolicy="no-referrer"><figcaption>${link(p.source,p.credit,'photo-credit')}</figcaption></figure>`:`<div class="hall-photo hall-photo-empty"><span>VIEWDDING</span><p>홀 사진 확인 중</p><small>상세 정보와 공식 출처를 먼저 살펴보세요.</small></div>`}
 function saveButton(h,overlay=false){return `<button class="${overlay?'hall-heart':'save-button'} ${hallSaved.has(h.id)?'saved':''}" data-hall-save="${e(h.id)}" aria-pressed="${hallSaved.has(h.id)}" aria-label="${e(h.name+' '+h.hall)} ${hallSaved.has(h.id)?'저장 취소':'저장'}">${icon(hallSaved.has(h.id)?'heartfill':'heart')}${overlay?'':` <span>${hallSaved.has(h.id)?'저장됨':'저장'}</span>`}</button>`}
 function capacityFacts(h){const fields=[['최소 보증',h.minimum],['최대 수용',h.capacity]].filter(([,v])=>v!==null&&v!==undefined);return fields.length?`<div class="hall-capacity"><dt>${fields.map(([label])=>label).join(' / ')}</dt><dd>${fields.map(([,value])=>people(value)).join(' / ')}</dd></div>`:''}
 function card(h){return `<article class="hall-card"><div class="hall-photo-wrap"><button class="hall-photo-button" data-hall-detail="${e(h.id)}" aria-label="${e(h.name+' '+h.hall)} 상세 보기">${photo(h).replace(/<figcaption>[\s\S]*?<\/figcaption>/,'')}</button>${saveButton(h,true)}</div><div class="hall-card-content"><div class="hall-card-head"><span>${e(h.region+' · '+h.district)}</span><button class="hall-title" data-hall-detail="${e(h.id)}"><strong>${e(h.name)}</strong><span>${e(h.hall)}</span></button></div><p class="hall-tags">${e((h.types.length?h.types:[h.type]).slice(0,3).join(' · '))}</p><dl class="hall-facts">${capacityFacts(h)}<div><dt>1인 식대</dt><dd>${h.mealPrice===null?'업체 문의':`${money(h.mealPrice)}부터`}</dd></div></dl><label class="hall-compare-check"><input type="checkbox" data-hall-compare="${e(h.id)}" ${compare.has(h.id)?'checked':''}>나란히 비교하기</label></div></article>`}
 function activeCount(){return ['query','region','district','guests','meal','parking','natural','private','interval'].filter(k=>filters[k]).length+filters.type.length+filters.regionBundles.length+filters.ceremonies.length+filters.meals.length}
 const ceremonyOptions=[['separate','분리예식'],['simultaneous','동시예식']];
 const mealOptions=[['buffet','뷔페'],['course','코스'],['korean','한식·한정식'],['catering','케이터링']];
 const copyFilters=()=>JSON.parse(JSON.stringify(filters));
 function results(){const list=matches();return `<div class="hall-result-toolbar"><p role="status" aria-live="polite">${filters.saved?'저장한 홀':'조건에 맞는 홀'} <strong>${n(list.length)}</strong><span>개</span></p><label>정렬<select id="hall-sort" data-hall-filter="sort"><option value="name"${selected(filters.sort,'name')}>가나다순</option><option value="popular" disabled>인기순 · 저장 수 집계 준비 중</option><option value="meal"${selected(filters.sort,'meal')}>식대 저렴한 순</option></select></label></div>${list.length?`<div class="hall-grid">${list.slice(0,limit).map(card).join('')}</div>${list.length>limit?`<div class="hall-more"><button class="outline-button" id="hall-more">웨딩홀 더 보기 (${Math.min(limit,list.length)} / ${n(list.length)}) ${icon('plus')}</button></div>`:''}`:`<div class="empty-state"><h2>${filters.saved?'저장한 홀 중 일치하는 곳이 없어요.':'조건에 맞는 웨딩홀이 없어요.'}</h2><p>${filters.saved?'마음에 드는 홀에서 저장을 누르거나, 검색 조건을 줄여보세요.':'지역이나 인원·식대 조건을 조금 넓혀보세요.'}</p><button class="outline-button" data-hall-reset>조건 초기화</button>${filters.saved?'<button class="text-button" data-hall-mode="all">전체 웨딩홀 보기 →</button>':''}</div>`}`}
 function compareBar(){const list=[...compare].map(byId).filter(Boolean);return list.length?`<div class="hall-compare-bar" aria-label="지금 비교 중인 홀"><div><strong>지금 비교 중 ${list.length} / 3</strong><div class="compare-chips">${list.map(h=>`<button data-hall-remove="${e(h.id)}" aria-label="${e(h.name+' '+h.hall)} 비교에서 빼기">${e(h.name)} · ${e(h.hall)} ×</button>`).join('')}</div></div><button class="solid-button" id="hall-compare-open" ${list.length<2?'disabled':''}>${list.length<2?'한 곳 더 선택하세요':'선택한 홀 비교하기'}</button></div>`:''}
 function filtersMarkup(){
  const f=draft||filters;
  const extra=Number(!!filters.guests)+Number(filters.natural)+filters.ceremonies.length+Number(!!filters.interval)+filters.meals.length;
  const selectedRegions=filters.regionBundles.map(id=>HallModel.bundles.find(b=>b.id===id)).filter(Boolean);
  const regionLabel=selectedRegions.length===1?selectedRegions[0].label:selectedRegions.length?'지역 · '+selectedRegions.length:'지역';
  const chip=(key,value,label,multi=false)=>{const active=multi?(value===''?!f[key].length:f[key].includes(value)):key==='natural'?f.natural:f[key]===value;return `<button id="hall-option-${key}-${e(value||'all')}" class="filter-button ${active?'active':''}" data-hall-option="${key}" data-value="${e(value)}" aria-pressed="${active}">${e(label)}</button>`};
  let contents='';
  if(openFilter==='region'){
   const group=HallRegions.groups.find(g=>g.id===regionGroup)||HallRegions.groups[0];
   contents=`<h2 id="hall-popover-title">지역</h2><p class="hall-filter-description">여러 지역을 함께 선택할 수 있어요.</p><div class="hall-region-picker"><div class="hall-region-groups" data-scroll-key="region-groups" aria-label="권역">${HallRegions.groups.map(g=>`<button id="hall-region-group-${g.id}" data-region-group="${g.id}" aria-pressed="${g.id===group.id}" class="${g.id===group.id?'active':''}">${e(g.name)}</button>`).join('')}</div><div class="hall-region-bundles" data-scroll-key="region-bundles-${group.id}" aria-label="${e(group.name)} 지역 묶음">${group.bundles.map(b=>`<button id="hall-bundle-${b.id}" class="filter-button ${f.regionBundles.includes(b.id)?'active':''}" data-region-bundle="${b.id}" aria-pressed="${f.regionBundles.includes(b.id)}">${e(b.label)}</button>`).join('')}</div></div>${f.regionBundles.length?`<div class="hall-region-selection">${f.regionBundles.map(id=>`<button data-region-bundle="${id}" aria-label="${e(HallModel.bundles.find(b=>b.id===id)?.label)} 선택 해제">${e(HallModel.bundles.find(b=>b.id===id)?.label)} ×</button>`).join('')}</div>`:''}`;
  }
  if(openFilter==='type')contents=`<h2 id="hall-popover-title">어떤 분위기를 원하세요?</h2><p class="hall-filter-description">여러 유형을 선택할 수 있어요. 선택한 유형 중 하나에 해당하는 홀을 보여드려요.</p><div class="hall-choice-grid hall-type-choices">${chip('type','','전체',true)}${types.map(v=>chip('type',v,v,true)).join('')}</div>`;
  if(openFilter==='detail')contents=`<h2 id="hall-popover-title">상세 조건</h2><section class="hall-reference-section"><h3>규모</h3><p class="hall-filter-description">식사 인원과 최소보증인원을 함께 고려해 찾습니다.</p><label class="hall-guest-field" for="hall-guests">예상 하객 수 <span><input id="hall-guests" type="number" inputmode="numeric" min="1" max="2000" step="1" placeholder="예: 200" value="${e(f.guests)}"><span>명</span></span></label></section><section class="hall-reference-section"><h3>예식 운영</h3><fieldset><legend>예식 형태</legend><div class="hall-option-row">${ceremonyOptions.map(([v,label])=>chip('ceremonies',v,label,true)).join('')}</div></fieldset><fieldset><legend>예식 간격</legend><div class="hall-option-row">${[70,90,120,180].map(v=>chip('interval',String(v),v+'분 이상')).join('')}</div></fieldset></section><section class="hall-reference-section"><h3>공간과 식사</h3><fieldset><legend>채광</legend><div class="hall-option-row">${chip('natural','yes','자연광 있음')}</div></fieldset><fieldset><legend>식사 종류</legend><div class="hall-option-row">${mealOptions.map(([v,label])=>chip('meals',v,label,true)).join('')}</div></fieldset></section>`;
  return `<div class="hall-filter-controls"><div class="hall-filter-triggers">${[['region',regionLabel,!!selectedRegions.length],['type',filters.type.length===1?filters.type[0]:filters.type.length?'홀 유형 · '+filters.type.length:'홀 유형',!!filters.type.length],['detail','상세 조건'+(extra?' · '+extra:''),!!extra]].map(([key,label,active])=>`<button id="hall-toggle-${key}" class="hall-filter-trigger ${active?'is-selected':''}" data-hall-panel="${key}" aria-expanded="${openFilter===key}" aria-controls="hall-filter-popover"><span>${e(label)}</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 7 5 5 5-5"/></svg></button>`).join('')}</div>${openFilter?`<section class="hall-filter-popover" id="hall-filter-popover" data-scroll-key="filter-${openFilter}" aria-labelledby="hall-popover-title"><button class="hall-popover-close icon-button" data-hall-close aria-label="검색 조건 닫기">${icon('close')}</button>${contents}<div class="hall-popover-footer"><button class="text-button" data-hall-reset-group="${openFilter}">초기화</button><button class="solid-button" id="hall-apply" data-hall-apply><span id="hall-apply-count">${n(HallModel.filter(all(),f,hallSaved).length)}개 웨딩홀 보기</span> ${icon('arrow')}</button></div></section>`:'<div id="hall-filter-popover" hidden></div>'}</div>`;
 }
 function activeFilters(){
  const labels={query:filters.query?'검색: '+filters.query:'',guests:filters.guests?filters.guests+'명':'',natural:filters.natural?'자연광':'',interval:filters.interval?filters.interval+'분 이상':''};
  const entries=Object.entries(labels).filter(([,v])=>v).map(([k,v])=>`<button data-hall-clear="${k}" aria-label="${e(v)} 조건 해제">${e(v)} <span aria-hidden="true">×</span></button>`);
  for(const [key,opts] of [['type',types.map(v=>[v,v])],['regionBundles',HallModel.bundles.map(b=>[b.id,b.label])],['ceremonies',ceremonyOptions],['meals',mealOptions]])for(const value of filters[key]){const label=opts.find(([id])=>id===value)?.[1]||value;entries.push(`<button data-hall-clear="${key}" data-value="${e(value)}" aria-label="${e(label)} 조건 해제">${e(label)} <span aria-hidden="true">×</span></button>`)}
  return entries.length?`<div class="hall-active-filters" aria-label="적용한 검색 조건">${entries.join('')}<button class="hall-reset-all" data-hall-reset>전체 초기화</button></div>`:'';
 }
 function closeFilter(restoreFocus=false){const key=openFilter;if(!key)return;openFilter='';draft=null;const panel=document.getElementById('hall-filter-popover');if(panel){panel.hidden=true;panel.innerHTML=''}document.getElementById('hall-toggle-'+key)?.setAttribute('aria-expanded','false');if(restoreFocus)document.getElementById('hall-toggle-'+key)?.focus({preventScroll:true})}
 function body(){if(error)return '<div class="empty-state"><h2>웨딩홀 목록을 불러오지 못했어요.</h2><button class="outline-button" id="hall-retry">다시 불러오기</button></div>';if(!db)return '<p class="hall-loading" role="status">웨딩홀 목록을 불러오고 있어요.</p>';return `<div class="hall-browse-tabs" aria-label="웨딩홀 목록"><button data-hall-mode="all" class="${!filters.saved?'active':''}" aria-pressed="${!filters.saved}">전체 웨딩홀 <span>${n(all().length)}</span></button><button data-hall-mode="saved" class="${filters.saved?'active':''}" aria-pressed="${filters.saved}">저장한 웨딩홀 <span>${all().filter(h=>hallSaved.has(h.id)).length}</span></button></div><section class="ui-filter-panel" aria-labelledby="hall-filter-heading"><h2 class="ui-panel-title" id="hall-filter-heading">검색 조건</h2><form id="hall-search-form" class="hall-search"><label class="sr-only" for="hall-query">웨딩홀 이름, 지역 또는 지하철역 검색</label><input type="search" id="hall-query" name="query" value="${e(filters.query)}" placeholder="웨딩홀 이름, 지역 또는 지하철역 검색" autocomplete="off"><button class="solid-button" type="submit">검색 ${icon('arrow')}</button></form>${filtersMarkup()}${activeFilters()}<div class="j-hall-actions"><button class="outline-button" data-j-criteria>${icon('survey')} 내 서베이 기준 적용</button><button class="outline-button" data-hall-view="list" aria-pressed="${hallView==='list'}">${icon('grid')} 목록</button><button class="outline-button" data-hall-view="map" aria-pressed="${hallView==='map'}">${icon('map')} 지도</button><a class="text-button" href="#excel">비교 · 엑셀 메뉴 ${icon('arrow')}</a></div></section><section class="hall-results" aria-label="웨딩홀 검색 결과">${hallView==='map'?Journal.hallMap():results()}</section><p class="note-label hall-data-note">목록 반영 ${db.asOf.replaceAll('-','. ')} · 공개 가능한 ${n(all().length)}개 홀<br>가격·시설 정보는 출처 확인일 기준입니다. 저장한 웨딩홀은 이 브라우저에 보관됩니다.</p>${compareBar()}`}
 function renderPage(){return `${heading('','웨딩홀 찾기','지역과 예산으로 좁히고, 마음에 드는 공간을 나란히 비교해보세요.')}${window.VenueSurvey?VenueSurvey.tabs('halls'):''}<div id="hall-explorer">${body()}</div>`}
 function repaint(){
  const container=document.querySelector('#hall-explorer');if(!container)return;
  const top=window.scrollY,left=window.scrollX;
  // Keep each scroll position only while that same panel/region remains on screen.
  const positions=new Map([...container.querySelectorAll('[data-scroll-key]')].map(el=>[el.dataset.scrollKey,{top:el.scrollTop,left:el.scrollLeft}]));
  const active=document.activeElement,id=active?.id;
  const key=['hallDetail','hallSave','hallCompare','hallMode','hallPanel','hallChoice','hallOption','regionBundle','regionGroup','hallResetGroup'].find(k=>active?.dataset?.[k]);
  const value=key?active.dataset[key]:null;
  container.innerHTML=body();
  if(id)document.getElementById(id)?.focus({preventScroll:true});
  else if(key){
   const attr=key.replace(/[A-Z]/g,m=>'-'+m.toLowerCase());
   const choice=active.dataset.value===undefined?'':`[data-value="${CSS.escape(active.dataset.value)}"]`;
   container.querySelector(`[data-${attr}="${CSS.escape(value)}"]${choice}`)?.focus({preventScroll:true});
  }
  container.querySelectorAll('[data-scroll-key]').forEach(el=>{const position=positions.get(el.dataset.scrollKey);if(position){el.scrollTop=position.top;el.scrollLeft=position.left}});
  window.scrollTo({left,top,behavior:'instant'});
  if(hallView==='map')Journal.afterRender();
 }

 function loadMore(){
  const list=matches(),start=limit,grid=document.querySelector('.hall-grid');
  const top=window.scrollY,left=window.scrollX;
  limit=Math.min(limit+12,list.length);
  if(grid){
   grid.insertAdjacentHTML('beforeend',list.slice(start,limit).map(card).join(''));
   const button=document.getElementById('hall-more');
   if(button){if(limit<list.length)button.innerHTML=`웨딩홀 더 보기 (${limit} / ${n(list.length)}) ${icon('plus')}`;else button.closest('.hall-more')?.remove()}
   if(list[start])grid.querySelector(`[data-hall-detail="${CSS.escape(list[start].id)}"]`)?.focus({preventScroll:true});
  }else repaint();
  window.scrollTo({left,top,behavior:'instant'});
 }
 async function loadData(){if(pending)return;pending=true;error=false;try{const res=await fetch('halls.json?v=5');if(!res.ok)throw Error('load');db=await res.json();if(!Array.isArray(db.halls))throw Error('shape');const ids=new Set(all().map(h=>h.id));hallSaved=new Set([...hallSaved].filter(id=>ids.has(id)));}catch{db=null;error=true}finally{pending=false;if(page==='halls')repaint();else if(['scrap','excel','collections'].includes(page))Journal.refresh()}}
 function detail(h){closeFilter();dialog.classList.add('hall-dialog');openDialog(`<div class="hall-detail-intro"><span class="section-eyebrow">${e(h.region+' · '+h.district)}</span><h2>${e(h.name)}</h2><p class="hall-detail-name">${e(h.hall)}</p><p>${e(h.types.join(' · '))}</p>${saveButton(h)}</div>${photo(h,true)}<div class="hall-detail-section"><h3>예식 공간</h3><dl class="hall-detail-facts">${[['최소 보증인원',people(h.minimum)],['착석인원',people(h.seats)],['최대 수용인원',people(h.capacity)],['예식 간격',h.interval===null?'확인 필요':n(h.interval)+'분'],['실내 · 야외',h.indoor||'확인 필요'],['예식 형태',h.ceremony||'확인 필요']].map(([a,b])=>`<div><dt>${a}</dt><dd>${e(b)}</dd></div>`).join('')}</dl><p class="hall-field-help">${h.review==='추정공개'?'홀 분위기·분류는 공개 자료에 따른 추정이 포함되어 있어요. 방문 상담에서 확인해주세요.':'공개 자료로 확인한 공간 정보입니다. 현재 운영 내용은 업체에 재확인해주세요.'}</p></div><div class="hall-detail-section"><h3>식사와 비용</h3><dl class="hall-detail-facts"><div><dt>1인 식대</dt><dd>${h.mealPrice===null?'업체 문의':money(h.mealPrice)+(h.mealPriceMax!==null&&h.mealPriceMax!==h.mealPrice?' ~ '+money(h.mealPriceMax):'부터')}</dd></div><div><dt>대관료</dt><dd>${h.rental===null?'업체 문의':money(h.rental)+(h.rentalMax!==null&&h.rentalMax!==h.rental?' ~ '+money(h.rentalMax):'부터')}</dd></div><div><dt>식사 유형</dt><dd>${e(h.meal||'확인 필요')}</dd></div></dl><p class="hall-field-help">${e(h.quoteConditions||'예식 날짜·요일·인원에 따라 견적이 달라질 수 있어요.')}<br>필수 옵션: ${e(h.quoteOptions||'업체 확인 필요')}<br>부가세·꽃장식·연출료의 포함 여부를 확인하세요.${h.quoteDate?'<br>가격 출처 확인일: '+e(h.quoteDate):''}</p>${link(h.quoteSource,'가격 출처 확인')}</div><div class="hall-detail-section"><h3>위치와 교통</h3><p>${e(h.address||'주소 확인 필요')}</p><dl class="hall-detail-facts"><div><dt>가까운 역</dt><dd>${e(h.station?(h.line+' '+h.station).trim():'확인 필요')}${h.walk!==null?' · 도보 '+n(h.walk)+'분':''}</dd></div><div><dt>주차 가능</dt><dd>${h.parking===null?'확인 필요':n(h.parking)+'대'}</dd></div><div><dt>무료 주차</dt><dd>${e(h.freeParking?h.freeParking+(/^\d+(\.\d+)?$/.test(h.freeParking)?'시간':''):'확인 필요')}</dd></div><div><dt>문의 전화</dt><dd>${e(h.phone||'확인 필요')}</dd></div></dl><div class="hall-detail-links">${link(h.map||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(h.name+' '+h.address),'지도에서 위치 보기','outline-button')}${link(h.website,'업체 안내 페이지','outline-button')}</div></div><div class="hall-detail-section"><h3>투어 전에 확인하세요</h3><ul><li>희망 날짜와 예식 시간의 예약 가능 여부</li><li>보증인원과 식대, 필수 옵션을 포함한 최종 견적</li><li>주차·하객 동선과 홀의 현재 모습</li></ul><p class="hall-field-help">정보 출처 확인일: ${e(h.verified||'확인 필요')} · 목록 반영: ${db.asOf}<br>예약을 진행하는 화면이 아닙니다. 상담은 업체 홈페이지에서 진행해주세요.</p>${link(h.source,'홀 정보 출처 확인')}</div>`)}
 function compareDialog(){const list=[...compare].map(byId).filter(Boolean);if(list.length<2)return;dialog.classList.add('hall-dialog');openDialog(`<span class="section-eyebrow">SIDE BY SIDE</span><h2>웨딩홀 나란히 비교</h2><p>같은 기준으로 확인하고 두 사람에게 중요한 조건부터 골라보세요.</p><div class="table-scroll" tabindex="0" role="region" aria-label="선택한 웨딩홀 비교 표"><table class="hall-compare-table"><thead><tr><th scope="col">비교 기준</th>${list.map(h=>`<th scope="col">${e(h.name)}<span>${e(h.hall)}</span></th>`).join('')}</tr></thead><tbody>${[['지역',h=>h.region+' '+h.district],['분위기',h=>h.types.join(' · ')||h.type],['최소 보증',h=>people(h.minimum)],['착석인원',h=>people(h.seats)],['최대 수용',h=>people(h.capacity)],['1인 식대',h=>h.mealPrice===null?'업체 문의':money(h.mealPrice)+'부터'],['대관료',h=>h.rental===null?'업체 문의':money(h.rental)+'부터'],['예식 간격',h=>h.interval===null?'확인 필요':n(h.interval)+'분'],['가까운 역',h=>h.station||'확인 필요'],['주차',h=>h.parking===null?'확인 필요':n(h.parking)+'대'],['가격 확인일',h=>h.quoteDate||'확인 필요']].map(([label,fn])=>`<tr><th scope="row">${label}</th>${list.map(h=>`<td>${e(fn(h))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">보관</th>${list.map(h=>`<td>${saveButton(h)}</td>`).join('')}</tr></tbody></table></div><p class="hall-field-help">공개된 기본가를 비교한 값입니다. 날짜·옵션에 따라 달라지므로 총견적은 업체에서 확인해주세요.</p>`)}
 function savedSection(){const count=all().filter(h=>hallSaved.has(h.id)).length;return `<section class="saved-hall-link"><div><span class="section-eyebrow">VENUE SHORTLIST</span><h2>저장한 웨딩홀 ${db?count:hallSaved.size}개</h2><p>공간·식대·인원을 확인하고 후보를 비교해보세요.</p></div><a href="#halls" class="outline-button" data-open-saved-halls>저장한 웨딩홀 보기 ${icon('arrow')}</a></section>`}
 window.VenueExplorer={all,repaint,matches,saved:()=>all().filter(h=>hallSaved.has(h.id)),compared:()=>[...compare].map(byId).filter(Boolean),card,applySurvey:next=>{filters={...HallModel.initial(),...next};limit=12;openFilter='';draft=null;},render:renderPage,savedSection,afterRender:()=>{if(!db&&!pending&&!error)loadData()}};
 document.addEventListener('submit',event=>{if(event.target.id!=='hall-search-form')return;event.preventDefault();filters.query=String(new FormData(event.target).get('query')||'').trim();limit=12;openFilter='';repaint();});
 document.addEventListener('change',event=>{
  const el=event.target;
  if(el.matches('[data-hall-filter]')){const key=el.dataset.hallFilter;filters[key]=el.type==='checkbox'?el.checked:el.value;if(key==='region')filters.district='';limit=12;repaint();}
  if(el.matches('[data-hall-compare]')){const id=el.dataset.hallCompare;if(!byId(id))return;if(el.checked&&compare.size>=3){el.checked=false;toast('한 번에 최대 3곳까지 비교할 수 있어요.');return}el.checked?compare.add(id):compare.delete(id);const active=id;repaint();document.querySelector(`[data-hall-compare="${CSS.escape(active)}"]`)?.focus({preventScroll:true});}
 });
 document.addEventListener('click',event=>{
  const el=event.target.closest('button,a');if(!el)return;
  if(el.dataset.hallPanel){openFilter=openFilter===el.dataset.hallPanel?'':el.dataset.hallPanel;draft=openFilter?copyFilters():null;repaint();return}
  if(el.hasAttribute('data-hall-close')){closeFilter(true);return}
  if(el.hasAttribute('data-hall-apply')){const input=document.getElementById('hall-guests');if(input&&!input.reportValidity())return;const key=openFilter;if(draft)filters=draft;draft=null;openFilter='';limit=12;repaint();document.getElementById('hall-toggle-'+key)?.focus({preventScroll:true});return}
  if(el.dataset.regionGroup){regionGroup=el.dataset.regionGroup;repaint();return}
  if(el.dataset.regionBundle&&draft){draft.regionBundles=HallModel.toggleBundle(draft.regionBundles,el.dataset.regionBundle);draft.region='';draft.district='';repaint();return}
  if(el.dataset.hallOption&&draft){const key=el.dataset.hallOption,value=el.dataset.value;if(Array.isArray(draft[key]))draft[key]=value===''?[]:draft[key].includes(value)?draft[key].filter(v=>v!==value):[...draft[key],value];else if(key==='natural')draft.natural=!draft.natural;else draft[key]=draft[key]===value?'':value;repaint();return}
  if(el.dataset.hallClear){closeFilter();const key=el.dataset.hallClear;filters[key]=Array.isArray(filters[key])?filters[key].filter(v=>v!==el.dataset.value):HallModel.initial()[key];limit=12;repaint();return}
  if(el.dataset.hallResetGroup&&draft){const keys={region:['regionBundles','region','district'],type:['type'],detail:['guests','natural','ceremonies','interval','meals']}[el.dataset.hallResetGroup];for(const key of keys||[])draft[key]=HallModel.initial()[key];repaint();return}
  if(el.hasAttribute('data-open-saved-halls')){filters=HallModel.initial();filters.saved=true;limit=12;}
  if(el.dataset.hallDetail){const h=byId(el.dataset.hallDetail);if(h)detail(h);}
  if(el.dataset.hallView){hallView=el.dataset.hallView;repaint();return}
  if(el.dataset.hallSave){const id=el.dataset.hallSave;if(!byId(id))return;hallSaved.has(id)?hallSaved.delete(id):hallSaved.add(id);const ok=persist();toast(ok?(hallSaved.has(id)?'이 브라우저에 저장했어요. 저장한 웨딩홀에서 다시 볼 수 있어요.':'저장한 웨딩홀에서 삭제했어요.'):'브라우저 저장을 사용할 수 없어 이번 방문 동안만 보관합니다.');document.querySelectorAll(`[data-hall-save="${CSS.escape(id)}"]`).forEach(b=>{b.classList.toggle('saved',hallSaved.has(id));b.setAttribute('aria-pressed',hallSaved.has(id));b.setAttribute('aria-label',byId(id).name+' '+byId(id).hall+' '+(hallSaved.has(id)?'저장 취소':'저장'));b.innerHTML=icon(hallSaved.has(id)?'heartfill':'heart')+(b.classList.contains('hall-heart')?'':' <span>'+(hallSaved.has(id)?'저장됨':'저장')+'</span>')});if(!dialog.open){repaint();if(page==='scrap')Journal.refresh();document.querySelector(`[data-hall-save="${CSS.escape(id)}"]`)?.focus({preventScroll:true})} }
  if(el.hasAttribute('data-hall-reset')){closeFilter();const isSaved=filters.saved;filters=HallModel.initial();filters.saved=isSaved;limit=12;repaint()}
  if(el.dataset.hallMode){filters.saved=el.dataset.hallMode==='saved';limit=12;repaint()}

  if(el.dataset.hallRemove){compare.delete(el.dataset.hallRemove);repaint()}
  if(el.id==='hall-more')loadMore()
  if(el.id==='hall-retry'){error=false;repaint();loadData()}
  if(el.id==='hall-compare-open')compareDialog();
 });
 document.addEventListener('input',event=>{if(event.target.id!=='hall-guests'||!draft)return;const input=event.target,value=Number(input.value);const valid=input.value===''||Number.isInteger(value)&&value>=1&&value<=2000;input.setCustomValidity(valid?'':'1명부터 2,000명까지 입력해주세요.');draft.guests=input.value===''?'':String(value);const count=document.getElementById('hall-apply-count');if(count)count.textContent=valid?n(HallModel.filter(all(),draft,hallSaved).length)+'개 웨딩홀 보기':'하객 수를 확인해주세요.'});
 document.addEventListener('pointerdown',event=>{if(openFilter&&!event.target.closest('.hall-filter-controls'))closeFilter()});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&openFilter){event.preventDefault();closeFilter(true)}});
 window.addEventListener('hashchange',()=>{openFilter='';draft=null});
 document.addEventListener('error',event=>{const img=event.target;if(img.tagName==='IMG'&&img.closest('.hall-photo')){img.hidden=true;const f=img.closest('.hall-photo');if(!f.querySelector('.photo-failed'))f.insertAdjacentHTML('afterbegin','<p class="photo-failed">사진을 불러올 수 없어요.<br>상세 보기에서 확인해주세요.</p>')}},true);
 document.addEventListener('DOMContentLoaded',()=>{dialog.addEventListener('close',()=>{dialog.classList.remove('hall-dialog');if(page==='halls')repaint()})});
})();
